using EduHelpdesk.Models; using EduHelpdesk.Services; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages;
namespace EduHelpdesk.Pages.Suppliers;
public class EditModel(HelpdeskStore store):PageModel { public SupplierRecord? Supplier{get;private set;} public void OnGet(Guid? id){Supplier=id.HasValue?store.Suppliers.FirstOrDefault(x=>x.Id==id):new(Guid.Empty,"","","","","","","","","","","","",DateTime.UtcNow);}  public IActionResult OnPost(SupplierRecord input){if(string.IsNullOrWhiteSpace(input.Name)){ModelState.AddModelError("","Supplier name is required.");Supplier=input;return Page();}var item=input with{Name=input.Name.Trim(),ContactName=input.ContactName?.Trim()??"",Email=input.Email?.Trim()??"",Phone=input.Phone?.Trim()??"",AddressLine1=input.AddressLine1?.Trim()??"",AddressLine2=input.AddressLine2?.Trim()??"",City=input.City?.Trim()??"",StateRegion=input.StateRegion?.Trim()??"",PostalCode=input.PostalCode?.Trim()??"",Country=input.Country?.Trim()??"",Website=input.Website?.Trim()??"",Notes=input.Notes?.Trim()??""};if(item.Id==Guid.Empty){store.AddSupplier(item with{Id=Guid.NewGuid(),CreatedAt=DateTime.UtcNow});TempData["Message"]="Supplier added.";}else{TempData["Message"]=store.UpdateSupplier(item)?"Supplier updated.":"Supplier was not found.";}return RedirectToPage("/Suppliers");}}
